    let hix = i16(((cptr.ldI16o2(svr, vlt, $sizeof_mkroom, $mkroom_hx) + 1) | 0));
    let loy = i16(((cptr.ldI16o2(svr, vlt, $sizeof_mkroom, $mkroom_ly) - 1) | 0));
    let hiy = i16(((cptr.ldI16o2(svr, vlt, $sizeof_mkroom, $mkroom_hy) + 1) | 0));
